<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {storeToday} from '../time'
import type {PayslipSummary} from '../payrollTypes'
import SegmentPayslips from '../components/SegmentPayslips.vue'
import SupplementalPayslips from '../components/SupplementalPayslips.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,r,t,base,loading,failure,load,english}=usePayrollPage(),year=ref(storeToday().slice(0,4)),items=ref<PayslipSummary[]>([]),selectedId=ref('')
const selected=computed(()=>items.value.find(p=>p.batchId===selectedId.value)||items.value[0])
function refresh(){if(!/^\d{4}$/.test(year.value)){failure.value=r('invalid');return}items.value=[];void load(()=>api().get<PayslipSummary[]>('/my-payslips?year='+year.value),v=>{items.value=v;selectedId.value=v[0]?.batchId||''})}
onMounted(()=>void load(async()=>{const latest=await api().get<{slip:PayslipSummary|null;supplementalMonth?:string|null;segmentMonth?:string|null}>('/my-latest-payslip');const lastMonth=[latest?.slip?.month,latest?.supplementalMonth,latest?.segmentMonth].filter((m):m is string=>typeof m==='string'&&/^\d{4}-(0[1-9]|1[0-2])$/.test(m)).sort().slice(-1)[0];const y=lastMonth?.slice(0,4)||year.value;return {year:y,items:await api().get<PayslipSummary[]>('/my-payslips?year='+y),id:latest?.slip?.batchId||''}},v=>{year.value=v.year;items.value=v.items;selectedId.value=v.id||v.items[0]?.batchId||''}))
</script>
<template><section class="wf-panel"><h2>{{r('myPayslips')}}</h2><form class="wf-filters" @submit.prevent="refresh"><label>{{r('year')}}<input v-model="year" required inputmode="numeric" pattern="\d{4}" maxlength="4"></label><button :disabled="loading">{{t('refresh')}}</button></form><PhaseStatus :failure="failure" :loading="loading"/><section v-if="selected&&!loading" class="wf-section"><h3>{{selected.month}} · {{selected.companyName}}</h3><p><strong>{{r('net')}} / {{english()?'Net payable this period':'本期应实发'}} SGD {{selected.netPay??'—'}}</strong></p><p>{{r('paid')}} {{selected.paidAmount}} · {{r('published')}}</p><p class="wf-hint">{{english()?'This is the amount payable. Publishing does not mean payment or bank receipt.':'应实发为本期应付金额；发布不代表已付款或银行到账。'}}</p><RouterLink class="wf-button primary" :to="base+'/payslips/'+selected.batchId">{{r('details')}}</RouterLink></section><div v-if="!loading" class="wf-table-wrap"><table><thead><tr><th>{{r('month')}}</th><th>{{r('company')}}</th><th>{{r('net')}}</th><th>{{r('paid')}}</th><th></th></tr></thead><tbody><tr v-for="v in items" :key="v.batchId"><td><button type="button" :aria-pressed="selected?.batchId===v.batchId" @click="selectedId=v.batchId">{{v.month}}</button></td><td>{{v.companyName}}</td><td>{{v.netPay}}</td><td>{{v.paidAmount}}</td><td><RouterLink :to="base+'/payslips/'+v.batchId">{{r('details')}}</RouterLink></td></tr><tr v-if="!items.length"><td colspan="5" class="wf-empty">{{t('empty')}}</td></tr></tbody></table></div><SegmentPayslips :year="year"/><SupplementalPayslips :year="year"/></section></template>
